// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {W_WALLET, Log} from "../src/W_WALLET.sol";

contract InvMutTest is Test {
    W_WALLET c;
    function setUp() public { c = new W_WALLET(address(new Log())); }
    function testFuzz_property(address actor, uint256 amount, uint256 unlockTime) public {
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 1000 ether);
        vm.deal(actor, amount);
        uint256 beforeBal;
        (, beforeBal) = c.Acc(actor);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);
        (, uint256 afterBal) = c.Acc(actor);
        assertTrue(afterBal == beforeBal + amount && address(c).balance == amount,
            "successful Put must credit caller's balance by msg.value");
    }
}
